  PRIMARY KEY (`id`),
  UNIQUE KEY `LeaderboardEntry_participantId_eventName_key` (`participantId`,`eventName`),
  KEY `LeaderboardEntry_eventName_idx` (`eventName`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
